// Android — Gradle flavors
android {
  flavorDimensions += "environment"
  productFlavors {
    create("dev") {
      dimension = "environment"
      applicationIdSuffix = ".dev"
      versionNameSuffix = "-dev"
      buildConfigField("String", "API_BASE", "\"https://dev.api/\"")
    }
    create("staging") {
      dimension = "environment"
      applicationIdSuffix = ".staging"
      buildConfigField("String", "API_BASE", "\"https://staging.api/\"")
    }
    create("prod") {
      dimension = "environment"
      buildConfigField("String", "API_BASE", "\"https://api.example.com/\"")
    }
  }
}

// Per-flavor source sets
// app/src/dev/res/values/strings.xml
// app/src/dev/AndroidManifest.xml — add a debug-only Activity

// Build a specific variant
// ./gradlew assembleDevDebug
// ./gradlew bundleProdRelease

// iOS — xcconfig per environment
// Configs/Dev.xcconfig:
//   API_BASE = https:/$()/dev.api
//   PRODUCT_BUNDLE_IDENTIFIER = com.example.app.dev
// Configs/Prod.xcconfig:
//   API_BASE = https:/$()/api.example.com
//   PRODUCT_BUNDLE_IDENTIFIER = com.example.app
//
// Build setting reads $(API_BASE); Info.plist contains <string>$(API_BASE)</string>
// Schemes pick which xcconfig to use.
//
// xcodebuild -scheme MyApp -configuration Dev build
// xcodebuild -scheme MyApp -configuration Prod archive

// Make the device a declared build input, so every run uses the same image
android {
  testOptions {
    managedDevices {
      localDevices {
        create("pixel8api36") {
          device = "Pixel 8"
          apiLevel = 36
          systemImageSource = "aosp-atd"   // no Play Store, no system apps: boots far faster
        }
      }
    }
    execution = "ANDROIDX_TEST_ORCHESTRATOR"   // a fresh process per test
    animationsDisabled = true
  }
  defaultConfig {
    testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
    testInstrumentationRunnerArguments["clearPackageData"] = "true"
  }
}

dependencies {
  androidTestUtil("androidx.test:orchestrator:1.6.1")
}

// Shard across runners rather than waiting longer
// ./gradlew pixel8api36DebugAndroidTest \
//   -Pandroid.testInstrumentationRunnerArguments.numShards=6 \
//   -Pandroid.testInstrumentationRunnerArguments.shardIndex=$SHARD

// Real hardware for what an emulator cannot show — nightly, not per PR
// gcloud firebase test android run --type instrumentation \
//   --device model=shiba,version=36 --device model=a54x,version=34 \
//   --num-flaky-test-attempts 1     // retry the test once; a repeat offender gets quarantined

